# python_run (Hayba) after a bpgraph build of CM_Saskarta and fix_array_nodes.py. Generated by
# Tools/GameFlow/gen_debug_specs.py: marks the console functions Exec and bakes the beat table.
import unreal
BEL = unreal.BlueprintEditorLibrary
bp = unreal.load_asset('/Game/SaskartaGaea/GameFlow/Debug/CM_Saskarta')
for name in ['SaskartaDebug', 'SaskartaTP', 'SaskartaBeat', 'SaskartaSkip', 'SaskartaResetBeats', 'SaskartaSpeed', 'SaskartaGod', 'SaskartaFly', 'SaskartaNext', 'SaskartaPrev', 'SaskartaStorm', 'SaskartaLook']:
    ge = unreal.BlueprintGraphEditor.get_graph_editor(BEL.find_graph(bp, name))
    ge.set_is_exec_function(True)
BEL.compile_blueprint(bp)
cdo = unreal.get_default_object(BEL.generated_class(bp))
cdo.set_editor_property('BeatIds', [unreal.Name(n) for n in ['B01_BOOT_HANDOVER', 'B02_ARCHIVE_OPENS', 'B03_PROMISE', 'B04_CART_CONVOY', 'B05_WAITING_WATER', 'B06_ROAD_AHEAD', 'B07_GEIGER_RISES', 'B08_NUMBERED_STOP', 'B09_DEPARTURE_PLATFORM', 'B10_DRY_CISTERN', 'OX1_EXCHANGE', 'B11_LAST_WAYSTATION', 'B12_KNEE_FAULT', 'OA1_OPTICS_FAIL', 'B13_SECOND_FAULT', 'OB1_DRONE_SOLO', 'OA2_OPTICS_BACK', 'OB1_DRONE', 'B14_LOOK_BACK', 'B15_HIGH_VOICE_IN_RANGE', 'B16_FAILING_STEPS', 'B17_CUT_OFF', 'B18_COLLAPSE', 'B19_REVEAL', 'B20_REST_BOULDER', 'B21_LAST_LOOK_BACK', 'B22_REST_HANDRAIL', 'B23_LAST_ENTRY', 'B24_TRANSMISSION']])
cdo.set_editor_property('BeatRoadMs', [0.0, 150.0, 450.0, 810.0, 1220.0, 1980.0, 2150.0, 2480.0, 2560.0, 3050.0, 3360.0, 3400.0, 3600.0, 3700.0, 4015.0, 4015.0, 4440.0, 4440.0, 4460.0, 4520.0, 4600.0, 4760.0, 4790.0, 4790.0, 4840.0, 4877.0, 4950.0, 4990.0, 4990.0])
status = str(bp.get_editor_property('status'))
if 'ERROR' not in status.upper():
    unreal.EditorAssetLibrary.save_loaded_asset(bp, False)
print('status', status, 'beats', len(cdo.get_editor_property('BeatIds')))
